// Package avrogen adapts this library through types generated by cmd/avrogen.
package avrogen

//go:generate go tool avrogen -pkg superhero -strict-types -encoders -o superhero/superhero.go ../../datasets/superhero/schema.avsc
//go:generate go tool avrogen -pkg nyctaxi -strict-types -encoders -initialisms MTA -o nyctaxi/nyctaxi.go ../../datasets/nyctaxi/schema.avsc

import (
	"github.com/iskorotkov/avro/bench/dataset"
	"github.com/iskorotkov/avro/bench/datasets/nyctaxi"
	"github.com/iskorotkov/avro/bench/datasets/superhero"
	"github.com/iskorotkov/avro/bench/format"
	"github.com/iskorotkov/avro/bench/formats/avro"
	gennyctaxi "github.com/iskorotkov/avro/bench/formats/avrogen/nyctaxi"
	gensuperhero "github.com/iskorotkov/avro/bench/formats/avrogen/superhero"
	avrolib "github.com/iskorotkov/avro/v2"
)

// Name is the format name; it is reported separately from the reflection-based baseline.
const Name = "avrogen"

// Format binds datasets that have generated types in this package.
type Format struct{}

// Name implements format.Format.
func (Format) Name() string { return Name }

// Bind implements format.Format.
func (Format) Bind(ds dataset.Dataset) (*format.Subject, error) {
	switch ds.Name() {
	case superhero.Name:
		return bind(ds, fromSuperhero, new(gensuperhero.Superhero).Schema())
	case nyctaxi.Name:
		return bind(ds, fromTrip, new(gennyctaxi.Trip).Schema())
	default:
		return nil, format.ErrUnsupported
	}
}

func bind[T, G any](ds dataset.Dataset, convert func(*T) *G, schema avrolib.Schema) (*format.Subject, error) {
	values, err := dataset.Convert(ds, convert)
	if err != nil {
		return nil, err
	}

	return avro.Subject(schema, values, func() any { return new(G) }), nil
}
